+		ERR_FAIL_COND_MSG(err != OK, "Could not remove directory: " + p_dir);
+		err = DirAccess::remove_absolute(p_dir);
+		ERR_FAIL_COND_MSG(err != OK, "Could not remove directory: " + p_dir);
+	}
+}
